mapper.update:
UPDATE oa_invoice
SET deleted_flag = #{deletedFlag}
WHERE invoice_id = #{invoiceId}

mapper.select:
SELECT *
FROM oa_invoice
WHERE enterprise_id = #{enterpriseId}
AND account_number = #{accountNumber}
AND deleted_flag = #{deletedFlag}

    AND invoice_id != #{excludeInvoiceId}

SELECT oa_invoice.*,
oa_enterprise.enterprise_name
FROM oa_invoice
LEFT JOIN oa_enterprise  ON oa_invoice.enterprise_id = oa_enterprise.enterprise_id

    oa_invoice.deleted_flag = #{queryForm.deletedFlag}

        AND (INSTR(oa_invoice.invoice_heads,#{queryForm.keywords}) OR INSTR(oa_invoice.account_number,#{queryForm.keywords}) OR
        INSTR(oa_invoice.create_user_name,#{queryForm.keywords}))


        AND DATE_FORMAT(oa_invoice.create_time, '%Y-%m-%d') >= #{queryForm.startTime}


        AND DATE_FORMAT(oa_invoice.create_time, '%Y-%m-%d') <= #{queryForm.endTime}


        AND oa_invoice.disabled_flag = #{queryForm.disabledFlag}


        AND oa_invoice.enterprise_id = #{queryForm.enterpriseId}



    ORDER BY oa_invoice.create_time DESC

SELECT oa_invoice.*,
       oa_enterprise.enterprise_name
FROM oa_invoice
LEFT JOIN oa_enterprise  ON oa_invoice.enterprise_id = oa_enterprise.enterprise_id
WHERE oa_invoice.invoice_id = #{invoiceId}
  AND oa_invoice.deleted_flag = #{deletedFlag}
